refentry.refsect1:
&reftitle.description;
public arrayIo\Poll\Watcher::getWatchedEvents
Returns the events that were last set with Io\Poll\Context::add, Io\Poll\Watcher::modify or Io\Poll\Watcher::modifyEvents. They remain available after the watcher was removed.

&reftitle.returnvalues;

 Returns a list of Io\Poll\Event cases, in the order in
 which the enum declares them.

  &reftitle.examples;

   Io\Poll\Watcher::getWatchedEvents example


<?php
use Io\Poll\Context;
use Io\Poll\Event;

[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$context = new Context();
$watcher = $context->add(new StreamPollHandle($reader), [Event::Read]);
var_dump($watcher->getWatchedEvents());

$watcher->modifyEvents([Event::Write, Event::Read]);
var_dump($watcher->getWatchedEvents());


   &example.outputs;


array(1) {
  [0]=>
  enum(Io\Poll\Event::Read)
}
array(2) {
  [0]=>
  enum(Io\Poll\Event::Read)
  [1]=>
  enum(Io\Poll\Event::Write)
}
